import sys
sys.path.insert(0,'.')
from helpers import spec,decline

def put(slug,anatomy,ac,moment,power,pc,setting,sc,nature,nc,variant,extra='',choices=None):
 def ids(ns):return [slug+'-c'+str(n).zfill(2) for n in ns]
 groups={'wujud':ids(ac),'kuasa':ids(pc),'tempat':ids(sc),'sifat':ids(nc)}
 req=[dict(kind='anatomy',description=anatomy,claim_ids=ids(ac)),dict(kind='setting',description=setting,claim_ids=ids(sc))]
 if pc:req.append(dict(kind='effect',description=power,claim_ids=ids(pc)))
 prompt=f'''ONE original square premium painterly cinematic Mitoloka illustration of {slug}, {variant}. Create one square PNG at least 1024 by 1024.
ANATOMY: {anatomy} [{', '.join(ids(ac))}]
MOMENT: {moment}
POWER: {power} [{', '.join(ids(pc))}]
SCALE & CAMERA: extreme low angle, confrontational close framing; subject fills 80 percent of the image, unmistakable silhouette at 200 pixels. {extra}
LIGHT & WEATHER: one dominant low-key warm moonlight or dusk source as appropriate, sharp rim light, deep walnut shadows, sparse contextual spray or dust; dark warm painterly palette with antique gold accent, no flat daylight.
SURFACE: tactile weathered natural materials, detailed rough skin, wet scales or coarse hair where anatomically appropriate; thick expressive oil brushwork and premium cinematic composition.
SETTING: {setting} [{', '.join(ids(sc))}]
MOOD: {nature}; overwhelming and imposing, never cute, calm, decorative or static. No modern costume.
HARD CONSTRAINTS: no text, no lettering, no symbols, no glyphs or pseudo-glyphs, no inscriptions, logo, border, frame or watermark; no extra heads, limbs, fingers or eyes; no design borrowed from any film, game, anime or comic; no nudity or explicit gore; no generic glow aura, neon outline or energy ribbons. Background subordinate to subject.'''
 spec(slug,groups,req,prompt,variant,(choices or [])+['Palet walnut/emas antik, kamera rendah dan konfrontasi rapat adalah pilihan editorial.','Cuaca, tekstur dan penutupan tubuh adalah pilihan visual, bukan fakta ikonografi baru.'],f'Kesan kekuatan dari {power if pc else anatomy}; '+', '.join(ids(pc if pc else ac))+'.')

put('lake-worth-monster','One part-man part-goat body, one goatlike head, two eyes, two arms with long five-fingered clawed hands, two goatlike legs; ragged fur mingled with clearly visible thick scales. No ornamental horns or armor.',[2,3,5],'Hurl a heavy worn unlettered car tire from a lakeside bluff directly toward the foreground, body lunging, teeth bared, one hand releasing the tire and the other braced against rock.','A physically hurled tire in the foreground, no magic.',[8],'Lake Worth bluff by Greer Island near Fort Worth; dark lake below.',[1,6],'Menacing attacking cryptid',[5],'Furred and scaled man-goat throwing a tire from the bluff',extra='Normal plausible creature size, no giant landscape scale.')
put('lantern-man','One disembodied atmospheric ghost light, no face, skull, limbs or humanoid figure: a dense natural amber-white flame-shaped apparition. It must be the dominant visible subject.',[1,3],'Surge close over reed beds and curl around the animal horn hanging at the end of a long wooden pole; the light is actively burning the horn.','The hanging horn burns and blackens under the ghost light; small orange embers and real smoke from contact, not neon or aura.',[6],'East Anglian Wicken Fen, wet reeds, mud and a pole projecting from a distant shadowed cottage.',[1],'Menacing spirit luring victims',[1,5],'Active disembodied ghost light scorching the distracting horn',extra='The apparition, horn and point of combustion fill the image; no landscape-only scene.',choices=['Manifestasi cahaya hantu aktif c01/c06, tanpa tubuh rekaan sesuai GAMBAR §6.5.','Warna api amber dan bentuk pusaran lokal adalah editorial; bukan wajah atau aura baru.'])
put('lava-bear','Very small ordinary black-bear-shaped animal with woolly light buckskin-brown fur.',[1,2,6],'No distinctive supernatural action documented.','No documented power; ordinary animal anatomy alone.',[],'South-central Oregon lava beds.',[1,8],'Ordinary stunted bear reports',[3,4],'Small woolly buckskin bear')
decline('lava-bear','Klaim c01/c02/c03/c04/c06/c07 menjelaskan beruang biasa sangat kecil/kerdil dengan bulu wol terang, tanpa pembeda supernatural atau manifestasi aktif. Menggambar beruang marah tetap hewan biasa; menambah kuasa lava atau ukuran raksasa akan mengarang. GAMBAR §6.1/§6.5.')
put('legend-of-trentren-vilu-and-caicai-vilu','Exactly two enormous limbless serpents with one head and two eyes each, long continuous bodies, no horns, wings or dragon legs. One sea serpent and one land serpent.',[1,4,6],'Clash face-to-face across the foreground, the sea serpent surging from the ocean left and the benevolent land serpent rising from mountains right to defend the high ground.','Sea flood surges and rocky hills rise, rock cracking and seawater foaming in the physical battle. No beams.',[5,12],'Chiloe archipelago and southern Chile mountains meeting the sea.',[2,3],'Awe-inspiring mythic confrontation; land serpent protective',[8],'Two serpents battling between rising flood and rising mountains',extra='Documented enormous scale; small mountain trees below their coils. Heads extremely prominent. No third serpent.',choices=['Varian dua ular dipilih; tidak mencampur varian burung/roh bukit c14.','Trentren digambar sebagai pelindung, bukan monster jahat.'])
put('lo-ting','One human-height fish-person with a dark humanlike face, short yellowish hair, two eyes, two arms and two legs, and a tiny one-cun tail at the lower back. Fully opaque plain dark linen torso and hip covering, legs visible; wet fishlike skin, no huge mermaid tail or extra fins.',[1,9],'Plunge forcefully from an oyster-shell island wall into dark seawater toward the foreground, twisting so the tiny tail is clearly visible; startled wide eyes face the viewer, splashing landing.','Forceful plunge into water when encountering people, a real close-up splash. No supernatural attack.',[9],'Island seashore around Dayushan, Hong Kong, with an oyster-shell wall.',[4,6,9],'Awe through unfamiliar fish-person anatomy; frightened harmless being, never evil',[10],'Dark-faced short-yellow-haired fish-person plunging into the sea',extra='Strictly human-sized; dominance only from close perspective, no tiny boats or giant scale.',choices=['Menyeleksi deskripsi Guangdong Xinyu c09, tidak meminjam keluarga putri duyung film c12.','Pakaian linen polos adalah penutupan editorial; tubuh bukan ikonografi film.'])
put('madre-de-aguas','One giant boa serpent as thick as a palm trunk, one head, two eyes, exactly two short horn-like projections on its head, heavy overlapping bullet-impenetrable scales; one continuous limbless body.',[3,4],'Haul backward into lagoon water while twisting the muscular coils toward the viewer, mouth opening in warning.','Powerful pull dragging an abandoned taut fishing line downward; deep water surges physically around the coils. No gunfire or invented power.',[9],'Cuban Laguna del Itabo, tropical lagoon and reed-lined water.',[5,8],'Awe-inspiring invulnerable water mother; do not make her a demonic villain',[6],'Palm-thick two-horned boa hauling back beneath lagoon water',extra='Documented giant thickness, a palm trunk behind for scale; close head and massive coils.')
put('mama-d-leau','One beautiful human female head with two eyes, two arms with five fingers each, torso fully covered in opaque unpatterned bronze-brown cloth, and one large snake body coiling continuously from the waist instead of legs. Long snaky hair, a narrow forked tongue briefly visible, and one plain golden comb with no inscriptions.',[3,4,7],'Emerge powerfully from the river and sweep a river current aside with the large snake coils while raising the comb through her long snaky hair; gaze commands the viewer.','Physical river displacement by her documented snake body, with river animals sheltering behind the coils; no conjured energy.',[2,7],'Caribbean river, rocky bank and dark tropical foliage.',[1,2,9],'Sacred protector and healer, benevolent yet overwhelming; dignified, never evil',[2,6,9],'River mother with serpent lower body and golden comb',extra='No unsupported giant scale, very close monumental composition only.',choices=['Varian tubuh ular c03/c07, tidak mencampur ekor ikan.','Pakaian polos buram adalah editorial untuk penutupan tubuh.','Cipratan berasal dari gerak tubuh di air, bukan kuasa badai rekaan.'])
put('mama-qucha','One pale beautiful young woman, one head, two eyes, two arms and two legs, completely clothed in an opaque plain Andean-inspired woven mantle and long robe, no symbols or ornamental crown.',[8],'Reach forward to settle a breaking sea wave, calm determined gaze down toward a small fishing boat, her outstretched palm over a suddenly smoothed channel.','Rough water becomes calm to protect fishermen; rough breakers beside a smooth passage to shore; no glowing spell.',[1,2],'Andean Pacific coastal sea, cliffs barely visible behind.',[5,9],'Revered benevolent Mother Sea; sacred awe, dignity and mercy',[1,9],'Mama Qucha calming a passage through rough sea',extra='Monumental goddess scale is explicitly an editorial sacred allegory under GAMBAR section 6.5, not a researched fact of bodily size. She fills the image and the tiny fishing boat anchors her protection.',choices=['Skala monumental dewi adalah alegori editorial penghormatan GAMBAR §6.5, bukan klaim ukuran c08.','Mantel/jubah polos adalah penutupan editorial, bukan ikonografi terdokumentasi.'])
put('maui-q1806741','One Maori demigod man with one head, two eyes, two muscular arms and two legs, hair bound in a clearly readable topknot. Opaque plain woven cloak, full torso covering and woven knee-length wrap; no tattoos or inscriptions. A huge plain bone fishhook shaped from an ancestress jawbone, on a thick cord held in both hands.',[3,7,10],'Haul violently backward in his canoe with the jawbone hook and line under tension, teeth clenched, looking at the viewer as land and the huge hooked fish surge from the ocean.','Superhuman strength fishes hidden land up from the sea using the ancestral jawbone hook; real heaving rock, water and foam.',[2,3,7],'New Zealand ocean at the emergence of the North Island, a plain canoe without carved symbols.',[3,4],'Culture hero in decisive overwhelming exertion; respectful and awe-inspiring',[1],'Topknotted Maui raising hidden land with ancestral jawbone fishhook',extra='Maui is not enlarged into a giant; close low camera in canoe, giant fish and emerging land documented. Prominent plain bone hook in foreground.',choices=['Wujud manusia dan pakaian buram polos adalah keputusan editorial; topknot dari nama c10.','Tidak memakai tato atau desain karakter film/game.'])
put('mazomba','One giant fish, a single large fish head with two lateral eyes, paired pectoral fins, one dorsal fin and tail fin; closed scaled body, no humanoid limbs, horns, beard or invented monster anatomy.',[1,3,4],'Rise almost vertically from the water close to the viewer, open the fish mouth as if speaking to a tiny lone woman on the near bank, imposing direct eye contact.','The giant fish addresses the woman; water physically pours off its lifted head, no magical effects.',[6,7],'Chaga tale water beside the route toward Mulungu; dark Tanzanian waters and bank.',[6,7],'Awe-inspiring talking giant fish, no predatory attack on the woman',[6,8],'Giant talking Mazomba addressing the traveler',extra='Documented giant fish; woman on bank far smaller than its head, opaque clothing. Fish dominates image.',choices=['Jenis ikan tidak ditentukan sumber; bentuk ikan bersisik umum adalah editorial.','Percakapan ditunjukkan melalui mulut terbuka dan arah pandang; tidak menambah kuasa unsur.'])
put('millalobo','One being the size of a large seal, with a humanlike chest and two arms, a lower body entirely sea-lion shaped with flippers instead of legs, and one face visibly blending a man and a sea lion. Two eyes, short shiny golden-yellow fur over the body; no fish tail, trident, crown or extra head.',[2,5,10,11],'Rear from the rocky shallows and thrust one hand toward a surging tide, mouth open in a forceful sea-lion bleat, gaze down directly at viewer.','Documented lordship over seas, directing tides and calms/storms: surf physically banks and divides around his command; no magic glow.',[4,12,14],'Chiloe sea in rocky shallows, dark water and sea floor behind.',[6,8,16],'Awe-inspiring sea ruler respected by benevolent and evil beings; not a villain',[7,12],'Golden-furred human and sea-lion sea ruler commanding the tide',extra='Strictly large-seal-sized, no unsupported giant scale; imposing only through extreme close low perspective.')
put('mirokutana','Nocturnal spirit in the ordinary form of a dog or wolf.',[1,2,6],'Roams at night; no distinctive active manifestation documented.','No powers specific to Mirokutana documented; do not borrow those of other spirits.',[],'Penas de Aya massif near Oiartzun, Gipuzkoa.',[1,6],'Nocturnal irelu spirit',[3],'Night spirit as dog or wolf')
decline('mirokutana','Klaim c01/c02/c06 hanya wujud anjing/serigala biasa dan berkeliaran malam; c04 secara eksplisit memisahkan kuasa tiap roh anjing menurut legenda. Tidak ada rupa pembeda atau manifestasi aktif Mirokutana yang dapat digambar tanpa mengambil kuasa roh lain. GAMBAR §6.1/§6.5.')
put('misshaku-kongo','One red-bodied Buddhist vajra guardian, one head, two glaring eyes, mouth wide open with bared teeth forming Ah, a topknot, exactly two arms and two bare feet. Fully opaque plain flowing temple cloth over chest and waist, no nudity. One plain metal vajra pestle firmly in one hand, the other hand opens palm with exactly five fingers. No inscriptions on weapon or clothing.',[1,2,3,8],'Strike the prison wall apart with the vajra pestle, body twisting toward the viewer in heroic protective exertion; fiercely compassionate protective face.','A prison wall breaks physically under the vajra blow, flying stone fragments and thick dust, liberation without gore.',[10],'Ancient Changan prison stone wall, unlettered plain masonry; no modern signs.',[10],'Majestic valiant dharmapala guardian, sacred awe and protection, never evil',[5,6,8],'Red topknotted Agyo guardian breaking prison masonry with vajra',extra='Sacred monumental guardian composition under GAMBAR section 6.5, not an asserted researched giant bodily size.',choices=['Kain buram pada dada untuk aturan tanpa ketelanjangan; c08 torso terbuka tidak digunakan secara telanjang.','Skala monumental adalah alegori editorial penghormatan GAMBAR §6.5, bukan fakta ukuran tubuh.'])
put('mogollon-monster','One ape-like biped over seven feet tall, one head with two large red eyes (red pigment, not glow), two arms and two legs. Long black and reddish-brown hair covers body except exposed rough face, chest, hands and feet. Humanlike hands exactly five fingers.',[1,2,5],'Lunge down toward the viewer with a large rough wooden club raised in one hand, other hand gripping rock, mouth open in a frightening scream.','Physical threat using a raised club; no gore, prey bodies or magic.',[10,12],'Arizona Mogollon Rim pine forest at night, rocky ledge.',[1,13],'Territorial violent nocturnal cryptid',[3,4],'Red-eyed long-haired Mogollon Monster threatening with club',extra='Documented over-seven-foot biped, trees serve subtle scale.')
put('moixina','One scowling strange old ogress with an aged humanlike face, two eyes, one head, two arms and two legs. Fully opaque coarse unpatterned ragged gown and shawl. One hand has exactly five fingers and grips a cluster of harsh thistle stalks as a crude comb, the other five-fingered hand reaches forward.',[1,2,3],'Lunge out of her cave toward the viewer, scowling and swinging the thistle comb in a threatening combing motion. No child victims.', 'Physical threatening use of the thistle comb, no spell or injury.',[2,3],'Catalan cave interior with jagged rocks and a narrow dusk-lit mouth.',[1,3],'Bad-tempered child-scaring ogress, unmistakably threatening',[2,6],'Cave ogress lunging with a thistle comb',extra='Do not enlarge into an unsupported giant; face and thistle weapon dominate a tight close low perspective, grotesque scowl but no extra monster anatomy.',choices=['Varian ogressa gua c01/c03; bukan varian nimfa kucing c07.','Wajah asing menggerutu lewat ekspresi dan kedekatan, tanpa taring/tanduk rekaan.'])
put('monai','One extraordinarily large limbless serpent, one head with two eyes, exactly two pointed spike-like antennae on its head, a mouth with clearly visible pointed teeth, long unbroken coils. No limbs, wings or extra horns.',[2,13],'Climb a tree and slide a huge upper coil down toward a bird halted in front of its two antennae, head facing viewer, jaws parting.','Bird entranced by hypnotic antennae holds still on a branch within reach, physically readable interaction; no hypnosis beams, aura or floating symbols.',[2],'Paraguayan field-edge tree close to dark swamp water near Yaguaron.',[4,12],'Dangerous mythic presence, without slaughter or attacks on people',[1,13],'Two-antenna huge serpent entrancing a bird as it descends a tree',extra='Documented extraordinary size; tree trunk small beside coils, close head. Antennae conspicuous as exactly two spikes.',choices=['Memilih varian perburuan/hipnosis c02; tidak menggambar korban manusia.','Hipnosis terbaca melalui arah antena dan burung yang diam, tanpa kuasa cahaya rekaan.'])
put('monopod-creature','One dwarf-like humanoid man, one head, two eyes, two arms, and EXACTLY ONE leg centered beneath his pelvis ending in ONE enormously broad human foot with exactly five toes. No second leg, stump, prosthesis or split limb. Opaque plain woven tunic and short wrap covering torso and hips.',[1,4,5],'Spring rapidly toward the viewer, sole giant foot launching from ground; single center leg clearly visible in uninterrupted silhouette, elbows driving forward, intense focused gaze.','Surprisingly fast jumping with one leg, dirt kicked from contact and long physical shadow from the large foot. No supernatural glow.',[5],'Hot Indian terrain of the ancient traveler tales, bare rock and dusty ground.',[3,4],'Imposing uncanny single-foot anatomy, not comic or cute',[1],'Monopod jumping rapidly on one central leg and one huge five-toed foot',extra='Dwarf-like actual size, no unsupported giant body. Low close camera makes the enormous documented foot and central single leg dominate.',choices=['Tubuh kecil sesuai c01; kaki raksasa saja yang besar sesuai c04.','Tunik buram editorial; aksi melompat c05 menggantikan pose teduh statis.'])
